using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace ShotOut {
partial class Editor {
    internal static bool ImageMovementIsLocked(Mark image){return image!=null&&image.Kind=="Image"&&(image.ImageMovementLocked??image.IsCaptureBase);}
    void ToggleImageMovement(Mark image){if(image==null||image.Kind!="Image"||!Marks.Contains(image))return;FinishStrokeAdjustment();Push();image.ImageMovementLocked=!ImageMovementIsLocked(image);ClearBackgroundClick();SyncLayers();UpdateInspector();View.Invalidate();UpdateStatus(ImageMovementIsLocked(image)?"Image movement locked":"Image movement unlocked");}
    internal bool HandleImageLockMouse(MouseEventArgs e){int at=layers.IndexFromPoint(e.Location);if(e.Button!=MouseButtons.Left||e.X<3||e.X>=24||at<0)return false;var image=layers.Items[at] as Mark;if(image==null||image.Kind!="Image")return false;layerDragging=null;effectDragCandidate=null;ToggleImageMovement(image);return true;}
    void AddImageMovementMenu(ContextMenuStrip menu){var images=SelectedObjects().Where(mark=>mark.Kind=="Image").ToList();if(images.Count==0)return;bool unlock=images.All(ImageMovementIsLocked);menu.Items.Add(unlock?"Unlock image movement":"Lock image movement",null,delegate{FinishStrokeAdjustment();Push();foreach(var image in images)image.ImageMovementLocked=!unlock;ClearBackgroundClick();SyncLayers();UpdateInspector();View.Invalidate();});}
    void VerifyImageMovementLocks(List<string> report,string folder){
        Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);report.Add("PASS "+label);};CloseImageEffects();LoadImageDocument(Blank(600,400),"Image movement locks");var original=Marks[0];check(ImageMovementIsLocked(original),"The first screenshot or opened image is movement locked by default");var added=new Mark {Kind="Image",Name="Added image",X=120,Y=80,W=200,H=140,Image=original.Image,Width=0};Marks.Add(added);RefreshImage();View.Zoom=1;View.PanX=View.PanY=0;Func<int,int,MouseEventArgs> mouse=(x,y)=>{var origin=View.Origin;return new MouseEventArgs(MouseButtons.Left,1,(int)origin.X+x,(int)origin.Y+y,0);};SetTool("Select");CanvasDownWithModifiers(mouse(180,130),Keys.None);CanvasMove(mouse(210,150));CanvasUp(mouse(210,150));check(added.X==150&&added.Y==100&&original.X==0&&original.Y==0,"Added images drag directly while the starting screenshot stays fixed");SetTool("Rectangle");Active=added;Selected.Clear();Selected.Add(added);CanvasDownWithModifiers(mouse(180,130),Keys.None);CanvasMove(mouse(220,160));CanvasUp(mouse(220,160));check(Marks.Last().Kind=="Rectangle"&&added.X==150&&added.Y==100,"Rectangle drawing wins over an unlocked selected image");SetTool("Rectangle");CanvasDownWithModifiers(mouse(30,30),Keys.None);CanvasMove(mouse(90,65));CanvasUp(mouse(90,65));check(Marks.Last().Kind=="Rectangle"&&original.X==0,"Drawing on the locked screenshot still creates annotations");
        Active=original;Selected.Clear();Selected.Add(original);SetTool("Select");Active=original;Selected.Add(original);SyncStyle();CanvasDownWithModifiers(mouse(500,300),Keys.None);CanvasMove(mouse(520,320));CanvasUp(mouse(520,320));check(original.X==0&&original.Y==0,"Selecting a locked screenshot does not unlock its canvas movement");ToggleImageMovement(original);SetTool("Select");CanvasDownWithModifiers(mouse(500,300),Keys.None);CanvasMove(mouse(520,320));CanvasUp(mouse(520,320));check(original.X==20&&original.Y==20,"Unlocking permits direct canvas dragging of the starting image");ToggleImageMovement(original);SyncLayers();int index=layers.Items.IndexOf(original);var row=layers.GetItemRectangle(index);check(HandleImageLockMouse(new MouseEventArgs(MouseButtons.Left,1,12,row.Top+20,0))&&!ImageMovementIsLocked(original),"The mini layer lock icon toggles image movement independently of visibility");
        Active=original;Selected.Clear();Selected.Add(original);using(var menu=DarkMenu()){AddImageMovementMenu(menu);check(menu.Items.Count==1&&menu.Items[0].Text=="Lock image movement","Image right-click menu offers the matching lock action");menu.Items[0].PerformClick();}check(ImageMovementIsLocked(original),"Context-menu locking keeps the original image protected");Active=original;Selected.Clear();Selected.Add(original);Duplicate();var duplicate=Marks.Last();check(duplicate.Kind=="Image"&&!duplicate.IsCaptureBase&&!ImageMovementIsLocked(duplicate),"Duplicated screenshots become ordinary unlocked images");ToggleImageMovement(original);var saved=Snapshot();using(var stream=new System.IO.MemoryStream()){var serializer=new System.Xml.Serialization.XmlSerializer(typeof(Project));serializer.Serialize(stream,saved);stream.Position=0;var restored=(Project)serializer.Deserialize(stream);check(!ImageMovementIsLocked(restored.Marks[0]),"Explicit unlock state persists in editable projects");}check(ImageMovementIsLocked(new Mark {Kind="Image",IsCaptureBase=true}),"Older screenshot layers without a saved lock setting receive the safe default");
        ToggleImageMovement(original);RefreshImage();using(var frame=new Bitmap(layers.Width,Math.Min(layers.Height,240))){layers.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(System.IO.Path.Combine(folder,"image-layer-locks.png"));}VerifyEffectsSurfacePolish(report,folder);
    }
}
}
